=-- Mark the sent reports. In test mode ({{ $('Config').first().json.TEST_MODE }} = true) nothing is marked, so tests can be repeated.
UPDATE reports SET emailed_at = now()
WHERE id = ANY(ARRAY[{{ $('Load unsent').all().map(i => i.json.id).join(',') }}]::bigint[]) AND emailed_at IS NULL AND NOT {{ $('Config').first().json.TEST_MODE }};
